// Offline GPS lot finder for the Zapotal residential lots (layout A).
// All geometry is in the survey's local metres (x = east, y = north); data.js is generated by scripts/field_data.py.
;(function () {
  const F = window.FIELD
  const T = {
    es: {
      start: 'Toca el botón verde para ver en qué lote estás.',
      ask: '¿En qué lote estás?',
      gpsBtn: 'Mostrar mi ubicación',
      retry: 'Intentar de nuevo',
      copy: 'Copiar enlace',
      copied: 'Enlace copiado',
      inapp: 'Abre este enlace en Chrome o Safari',
      inappSub: 'WhatsApp, Instagram y Facebook no dejan usar el GPS aquí.',
      inappSteps: ['Toca «Copiar enlace».', 'Abre Chrome (Android) o Safari (iPhone).', 'Pega el enlace arriba y ábrelo.'],
      deniedIos: ['Abre Ajustes → Privacidad y seguridad → Localización. Actívala.', 'En la misma lista, toca «Sitios web de Safari» (o Chrome) → «Al usar la app».', 'Vuelve aquí y toca «Intentar de nuevo».'],
      deniedAnd: ['Baja la barra de arriba del teléfono y activa «Ubicación».', 'En Chrome, toca el candado o ⓘ junto a la dirección → Permisos → Ubicación → Permitir.', 'Vuelve aquí y toca «Intentar de nuevo».'],
      timeout: 'El GPS todavía no responde',
      timeoutSub: 'Activa «Ubicación» en el teléfono, sal al aire libre y toca «Intentar de nuevo».',
      wait: 'Buscando tu ubicación…',
      waitSub: 'Sal al aire libre y espera unos segundos.',
      denied: 'Sin permiso de ubicación',
      deniedSub: 'Permite la ubicación para esta página en los ajustes del teléfono.',
      nogps: 'Este teléfono no da ubicación',
      lot: 'Estás en el Lote',
      view: 'Vista al mar',
      v_good: 'amplia', v_part: 'sí', v_none: 'no',
      nearLot: 'Cerca del límite con el Lote',
      nearLane: 'Cerca del camino privado',
      nearEdge: 'Cerca del límite del terreno',
      lane: 'Estás en el camino privado',
      laneSub: 'Camino de 3 m que sube a los lotes.',
      road: 'Estás en el camino de 6 m',
      roadSub: 'Entrada desde V1 hacia la escuela.',
      school: 'Terreno de la escuela',
      schoolSub: 'Donación para la Escuela Tribu (2,500 m²).',
      rest: 'Resto del predio',
      restSub: 'Esta zona no está en venta.',
      out: 'Estás fuera del terreno',
      far: 'Estás lejos del terreno',
      toLot: 'Lote', toward: 'a', to: 'hacia el', dir: ['norte', 'noreste', 'este', 'sureste', 'sur', 'suroeste', 'oeste', 'noroeste'],
      weak: 'Señal GPS débil (±{a} m). Espera al aire libre, lejos de los árboles.',
      acc: 'Precisión ±{a} m',
      go3d: 'Ver en 3D (con internet)',
      save: 'Guardar en mi teléfono',
      saved: 'Ya está guardado en este teléfono',
      note: 'Ubicación aproximada. Los linderos finales se marcarán con topógrafo.',
      iosTitle: 'Para guardar en el iPhone:',
      ios: ['Toca el botón Compartir (el cuadro con la flecha hacia arriba).', 'Elige «Agregar a inicio».', 'Toca «Agregar». Abre la página desde ese icono.'],
      other: ['Abre el menú del navegador (⋮).', 'Elige «Instalar app» o «Agregar a la pantalla de inicio».'],
      m2: 'm²',
    },
    en: {
      start: 'Tap the green button to see which lot you are in.',
      ask: 'Which lot are you in?',
      gpsBtn: 'Show my location',
      retry: 'Try again',
      copy: 'Copy link',
      copied: 'Link copied',
      inapp: 'Open this link in Chrome or Safari',
      inappSub: 'WhatsApp, Instagram and Facebook block the GPS here.',
      inappSteps: ['Tap “Copy link”.', 'Open Chrome (Android) or Safari (iPhone).', 'Paste the link at the top and open it.'],
      deniedIos: ['Open Settings → Privacy & Security → Location Services. Turn it on.', 'In the same list, tap “Safari Websites” (or Chrome) → “While Using the App”.', 'Come back here and tap “Try again”.'],
      deniedAnd: ['Pull down the top bar of the phone and turn on “Location”.', 'In Chrome, tap the lock or ⓘ next to the address → Permissions → Location → Allow.', 'Come back here and tap “Try again”.'],
      timeout: 'The GPS does not answer yet',
      timeoutSub: 'Turn on “Location” on the phone, step outside and tap “Try again”.',
      wait: 'Finding your location…',
      waitSub: 'Step outside and wait a few seconds.',
      denied: 'No location permission',
      deniedSub: 'Allow location for this page in the phone settings.',
      nogps: 'This phone gives no location',
      lot: 'You are in Lot',
      view: 'Sea view',
      v_good: 'wide', v_part: 'yes', v_none: 'no',
      nearLot: 'Near the border with Lot',
      nearLane: 'Near the private lane',
      nearEdge: 'Near the edge of the land',
      lane: 'You are on the private lane',
      laneSub: '3 m lane that climbs to the lots.',
      road: 'You are on the 6 m road',
      roadSub: 'Entrance from V1 towards the school.',
      school: 'School land',
      schoolSub: 'Donated to Escuela Tribu (2,500 m²).',
      rest: 'Rest of the property',
      restSub: 'This area is not for sale.',
      out: 'You are outside the land',
      far: 'You are far from the land',
      toLot: 'Lot', toward: '', to: 'to the', dir: ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'],
      weak: 'Weak GPS signal (±{a} m). Wait in the open, away from trees.',
      acc: 'Accuracy ±{a} m',
      go3d: 'See in 3D (needs internet)',
      save: 'Save on my phone',
      saved: 'Already saved on this phone',
      note: 'Approximate location. The final boundaries will be marked by a surveyor.',
      iosTitle: 'To save on the iPhone:',
      ios: ['Tap the Share button (the square with the up arrow).', 'Choose “Add to Home Screen”.', 'Tap “Add”. Open the page from that icon.'],
      other: ['Open the browser menu (⋮).', 'Choose “Install app” or “Add to Home screen”.'],
      m2: 'm²',
    },
  }
  let lang = 'es'
  try { lang = localStorage.getItem('zf-lang') || 'es' } catch (e) {}
  const s = (k) => T[lang][k]
  const isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1)
  const fmt = (n) => Math.round(n).toLocaleString('en-US')

  // ---------- geometry ----------
  const R = F.ref
  const toLocal = (lat, lon) => {
    const a = lon - R.lon0, b = lat - R.lat0
    return [R.cx[0] * a + R.cx[1] * b, R.cy[0] * a + R.cy[1] * b]
  }
  function inside(p, poly) {
    let c = false
    for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
      const [xi, yi] = poly[i], [xj, yj] = poly[j]
      if (yi > p[1] !== yj > p[1] && p[0] < ((xj - xi) * (p[1] - yi)) / (yj - yi) + xi) c = !c
    }
    return c
  }
  function segDist(p, a, b) {
    const dx = b[0] - a[0], dy = b[1] - a[1]
    const t = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / (dx * dx + dy * dy || 1)))
    return Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dy)
  }
  const lineDist = (p, pts) => { let d = Infinity; for (let i = 0; i < pts.length - 1; i++) d = Math.min(d, segDist(p, pts[i], pts[i + 1])); return d }
  const edgeDist = (p, poly) => lineDist(p, [...poly, poly[0]])
  const centroid = (poly) => {
    let a = 0, x = 0, y = 0
    for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
      const f = poly[j][0] * poly[i][1] - poly[i][0] * poly[j][1]
      a += f; x += (poly[j][0] + poly[i][0]) * f; y += (poly[j][1] + poly[i][1]) * f
    }
    return [x / (3 * a), y / (3 * a)]
  }
  const onLane = (p) => lineDist(p, F.lane) <= 1.6 || Math.hypot(p[0] - F.turn[0], p[1] - F.turn[1]) <= 5
  const dirWord = (dx, dy) => s('dir')[Math.round(((Math.atan2(dx, dy) * 180) / Math.PI + 360) / 45) % 8]
  const viewWord = (v) => (v >= 0.55 ? s('v_good') : v >= 0.2 ? s('v_part') : s('v_none'))

  // ---------- map ----------
  const svg = document.getElementById('map')
  const NS = 'http://www.w3.org/2000/svg'
  const all = [...F.residential, ...F.donation, ...F.road]
  const minX = Math.min(...all.map((p) => p[0])) - 6, maxX = Math.max(...all.map((p) => p[0])) + 6
  const minY = Math.min(...all.map((p) => p[1])) - 6, maxY = Math.max(...all.map((p) => p[1])) + 6
  svg.setAttribute('viewBox', `${minX} ${-maxY} ${maxX - minX} ${maxY - minY}`)
  svg.setAttribute('preserveAspectRatio', 'xMidYMid meet')
  const P = (pts) => pts.map((p) => `${p[0].toFixed(2)},${(-p[1]).toFixed(2)}`).join(' ')
  const el = (tag, attrs, parent = svg) => {
    const e = document.createElementNS(NS, tag)
    for (const k in attrs) e.setAttribute(k, attrs[k])
    parent.appendChild(e)
    return e
  }
  el('polygon', { points: P(F.road), class: 'road' })
  el('polygon', { points: P(F.donation), class: 'school' })
  const lotEls = F.lots.map((l) => el('polygon', { points: P(l.poly), class: 'lot' }))
  F.contours.forEach((c) => el('polyline', { points: P(c.p), class: 'cont' }))
  F.lots.forEach((l) => el('polygon', { points: P(l.pad), class: 'pad' }))
  el('polyline', { points: P(F.lane), class: 'lane' })
  el('circle', { cx: F.turn[0], cy: -F.turn[1], r: 5, class: 'turn' })
  el('polygon', { points: P(F.boundary), class: 'bnd' })
  const labels = F.lots.map((l) => {
    const c = centroid(l.poly)
    const t1 = el('text', { x: c[0], y: -c[1], class: 'lbl' })
    const t2 = el('text', { x: c[0], y: -c[1] + 6, class: 'lbl2' })
    return { l, t1, t2 }
  })
  const dc = centroid(F.donation)
  const schoolTag = el('text', { x: dc[0], y: -dc[1], class: 'tag' })
  const nx = maxX - 8, ny = -maxY + 12
  el('path', { d: `M${nx},${ny - 8} l3,7 l-3,-2 l-3,2 z`, fill: '#1d2a20' })
  el('text', { x: nx, y: ny + 6, class: 'north' }).textContent = 'N'
  const acc = el('circle', { class: 'acc', r: 0, cx: -9999, cy: 0 })
  const dot = el('circle', { class: 'dot', r: 2.6, cx: -9999, cy: 0 })

  // ---------- status ----------
  const $ = (id) => document.getElementById(id)
  let last = null // { p: [x, y], a: accuracy m }
  let state = 'wait'

  function setText(title, sub, hint) {
    $('title').textContent = title
    $('sub').textContent = sub || ''
    $('hint').textContent = hint || ''
  }

  function render() {
    labels.forEach(({ l, t1, t2 }) => { t1.textContent = String(l.id); t2.textContent = `${fmt(l.area)} ${s('m2')}` })
    schoolTag.textContent = lang === 'es' ? 'Escuela' : 'School'
    $('lang').textContent = lang === 'es' ? 'EN' : 'ES'
    $('go3d').textContent = s('go3d')
    $('note').textContent = s('note')
    document.documentElement.lang = lang
    renderSave()
    lotEls.forEach((e) => e.classList.remove('on'))
    $('help').innerHTML = ''
    $('gpsBtn').hidden = true
    $('copyBtn').hidden = true
    $('copyBtn').textContent = s('copy')
    if (!last) {
      const steps = (k) => `<ol>${s(k).map((x) => `<li>${x}</li>`).join('')}</ol>`
      if (inApp) {
        setText(s('inapp'), s('inappSub'))
        $('help').innerHTML = steps('inappSteps')
        $('copyBtn').hidden = false
        $('gpsBtn').hidden = false; $('gpsBtn').textContent = s('gpsBtn')
      } else if (state === 'denied') {
        setText(s('denied'), '')
        $('help').innerHTML = steps(isIOS ? 'deniedIos' : 'deniedAnd')
        $('gpsBtn').hidden = false; $('gpsBtn').textContent = s('retry')
      } else if (state === 'timeout') {
        setText(s('timeout'), s('timeoutSub'))
        $('gpsBtn').hidden = false; $('gpsBtn').textContent = s('retry')
      } else if (state === 'nogps') setText(s('nogps'), '')
      else if (state === 'idle') {
        setText(s('ask'), s('start'))
        $('gpsBtn').hidden = false; $('gpsBtn').textContent = s('gpsBtn')
      } else setText(s('wait'), s('waitSub'))
      return
    }
    const { p, a } = last
    dot.setAttribute('cx', p[0]); dot.setAttribute('cy', -p[1])
    acc.setAttribute('cx', p[0]); acc.setAttribute('cy', -p[1]); acc.setAttribute('r', Math.min(a, 60))
    const accLine = a > 25 ? s('weak').replace('{a}', Math.round(a)) : s('acc').replace('{a}', Math.round(a))
    const near = Math.max(5, Math.min(a, 15))

    const i = F.lots.findIndex((l) => inside(p, l.poly))
    if (i >= 0) {
      const l = F.lots[i]
      lotEls[i].classList.add('on')
      // what is the closest border?
      let hint = ''
      if (edgeDist(p, l.poly) < near) {
        let best = null
        F.lots.forEach((o, j) => { if (j !== i) { const d = edgeDist(p, o.poly); if (!best || d < best.d) best = { d, w: `${s('nearLot')} ${o.id}` } } })
        const dl = lineDist(p, F.lane) - 1.5
        if (dl < (best ? best.d : Infinity)) best = { d: dl, w: s('nearLane') }
        hint = best && best.d < near + 3 ? best.w : s('nearEdge')
      }
      setText(`${s('lot')} ${l.id} · ${fmt(l.area)} ${s('m2')}`, `${s('view')}: ${viewWord(l.view)}`, [hint, a > 25 ? accLine : ''].filter(Boolean).join(' · ') || accLine)
      if (!hint && a <= 25) $('hint').style.color = 'var(--muted)'
      else $('hint').style.color = ''
      return
    }
    $('hint').style.color = a > 25 ? '' : 'var(--muted)'
    if (onLane(p)) return setText(s('lane'), s('laneSub'), accLine)
    if (inside(p, F.road)) return setText(s('road'), s('roadSub'), accLine)
    if (inside(p, F.donation)) return setText(s('school'), s('schoolSub'), accLine)
    if (inside(p, F.boundary)) return setText(s('rest'), s('restSub'), accLine)
    // outside: point to the nearest lot
    let best = null
    F.lots.forEach((l) => { const d = edgeDist(p, l.poly); if (!best || d < best.d) best = { d, l } })
    const c = centroid(best.l.poly)
    const far = best.d > 2000
    const dist = far ? `${(best.d / 1000).toFixed(1)} km` : `${fmt(best.d)} m`
    setText(far ? s('far') : s('out'), `${s('toLot')} ${best.l.id}: ${s('toward') ? s('toward') + ' ' : ''}${dist} ${s('to')} ${dirWord(c[0] - p[0], c[1] - p[1])}`, accLine)
  }

  // ---------- GPS ----------
  const demo = /[?&]demo\b/.test(location.search)
  if (demo) {
    svg.addEventListener('click', (ev) => {
      const pt = svg.createSVGPoint(); pt.x = ev.clientX; pt.y = ev.clientY
      const q = pt.matrixTransform(svg.getScreenCTM().inverse())
      last = { p: [q.x, -q.y], a: 6 }
      render()
    })
  }
  // In-app browsers (WhatsApp, Instagram, Facebook…) often block location: ask to open in Chrome/Safari.
  const ua = navigator.userAgent
  const inApp = /WhatsApp|Instagram|FBAN|FBAV|FB_IAB|Line\/|Telegram|; wv\)/i.test(ua)
  let watchId = null
  let gotFix = false
  function startGps() {
    if (!('geolocation' in navigator)) { state = 'nogps'; return render() }
    if (watchId !== null) navigator.geolocation.clearWatch(watchId)
    state = 'wait'; gotFix = false; render()
    const ok = (pos) => {
      gotFix = true
      try { localStorage.setItem('zf-gps', '1') } catch (e) {}
      if (demo && last) return
      last = { p: toLocal(pos.coords.latitude, pos.coords.longitude), a: pos.coords.accuracy }
      render()
    }
    const fail = (err) => {
      if (gotFix) return
      state = err.code === 1 ? 'denied' : 'timeout'
      if (err.code === 1) { try { localStorage.removeItem('zf-gps') } catch (e) {} }
      render()
    }
    // one quick request from the tap (this is what shows the permission question), then keep following
    navigator.geolocation.getCurrentPosition(ok, (err) => { if (err.code === 1) fail(err) }, { enableHighAccuracy: true, maximumAge: 10000, timeout: 20000 })
    watchId = navigator.geolocation.watchPosition(ok, fail, { enableHighAccuracy: true, maximumAge: 2000, timeout: 45000 })
  }
  $('gpsBtn').onclick = startGps
  $('copyBtn').onclick = async () => {
    const url = location.origin + location.pathname
    try { await navigator.clipboard.writeText(url) } catch (e) { window.prompt(s('copy'), url) }
    $('copyBtn').textContent = s('copied')
  }
  // ---------- language ----------
  $('lang').onclick = () => {
    lang = lang === 'es' ? 'en' : 'es'
    try { localStorage.setItem('zf-lang', lang) } catch (e) {}
    render()
  }

  // ---------- save on phone ----------
  let prompt = null
  const standalone = () => window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true
  window.addEventListener('beforeinstallprompt', (e) => { e.preventDefault(); prompt = e; renderSave() })
  window.addEventListener('appinstalled', () => { prompt = null; renderSave() })
  function renderSave() {
    const b = $('save')
    if (standalone()) { b.textContent = s('saved'); b.disabled = true; b.style.opacity = 0.6 }
    else { b.textContent = s('save'); b.disabled = false; b.style.opacity = 1 }
  }
  $('save').onclick = async () => {
    if (prompt) { prompt.prompt(); try { await prompt.userChoice } catch (e) {} prompt = null; return renderSave() }
    const steps = isIOS ? s('ios') : s('other')
    $('sheetText').innerHTML = `<b>${isIOS ? s('iosTitle') : s('save')}</b><ol>${steps.map((x) => `<li>${x}</li>`).join('')}</ol>`
    $('sheet').classList.add('open')
  }
  $('sheetOk').onclick = () => $('sheet').classList.remove('open')

  if ('serviceWorker' in navigator) navigator.serviceWorker.register('sw.js').catch(() => {})
  // start the GPS by itself when the permission is already given; else wait for the tap on the green button.
  // Runs last, after every function render() needs is defined.
  state = 'idle'
  render()
  if (!inApp) {
    let known = false
    try { known = localStorage.getItem('zf-gps') === '1' } catch (e) {}
    if (known) startGps()
    else if (navigator.permissions && navigator.permissions.query)
      navigator.permissions.query({ name: 'geolocation' }).then((p) => { if (p.state === 'granted') startGps() }).catch(() => {})
  }
})()
